callGraph.callee:
generateLeagueTableAction({
        leagueId: p.currentClub.leagueId,
        playerClubId: p.currentClub.id,
        playerClubName: p.currentClub.name,
        playerStanding: standingVal,
      }).then((mockTable) => {
        p.setSeasonRecords((prev) => {
          const rec = { ...prev[p.currentAge] };
          rec.standing = standingVal;
          rec.leagueTable = mockTable;
          return { ...prev, [p.currentAge]: rec };
        });
        p.setActiveModal("league");
        p.setCareerSubStep("domestic_cup");
        p.setIsProcessing(false);
      }).catch

generateLeagueTableAction({
        leagueId: p.currentClub.leagueId,
        playerClubId: p.currentClub.id,
        playerClubName: p.currentClub.name,
        playerStanding: standingVal,
      }).then

generateCupJourneyAction({
        type: "domestic",
        result: cupVal,
        playerClubId: p.currentClub.id,
        playerClubPrestige: p.currentClub.prestige ?? 3,
      }).then((journey) => {
        p.setSeasonRecords((prev) => {
          const rec = { ...prev[p.currentAge] };
          rec.domesticCup = cupVal;
          rec.domesticCupJourney = journey;
          return { ...prev, [p.currentAge]: rec };
        });
        p.setActiveModal("cup");
        if (p.currentContinentalCup !== "none") {
          p.setCareerSubStep("continental_cup");
          p.setIsProcessing(false);
        } else {
          const next = p.checkNationalCallupTransition();
          if (next === "national_callup") {
            p.setCareerSubStep("national_callup");
            p.setIsProcessing(false);
          } else {
            triggerSeasonStats(p.standingResult, cupVal, p.continentalCupResult, null, null);
          }
        }
      }).catch

generateCupJourneyAction({
        type: "domestic",
        result: cupVal,
        playerClubId: p.currentClub.id,
        playerClubPrestige: p.currentClub.prestige ?? 3,
      }).then

generateCupJourneyAction({
        type: "continental",
        result: contVal,
        playerClubId: p.currentClub.id,
        playerClubPrestige: p.currentClub.prestige ?? 3,
        cupName: cupLabel,
        cupType: p.currentContinentalCup,
      }).then((journey) => {
        p.setSeasonRecords((prev) => {
          const rec = { ...prev[p.currentAge] };
          if (rec.continentalCup) rec.continentalCup.result = contVal;
          rec.continentalCupJourney = journey;
          return { ...prev, [p.currentAge]: rec };
        });
        p.setActiveModal("continental");
        const next = p.checkNationalCallupTransition();
        if (next === "national_callup") {
          p.setCareerSubStep("national_callup");
          p.setIsProcessing(false);
        } else {
          triggerSeasonStats(p.standingResult, p.domesticCupResult, contVal, null, null);
        }
      }).catch

generateCupJourneyAction({
        type: "national",
        result: tournamentVal,
        playerClubId: p.currentClub.id,
        playerClubPrestige: p.currentClub.prestige ?? 3,
        cupName: tourney,
        playerNationality: p.playerNationality,
      }).then((journey) => {
        p.setSeasonRecords((prev) => {
          const rec = { ...prev[p.currentAge] };
          if (rec.nationalTeam) rec.nationalTeam.result = tournamentVal;
          rec.nationalTeamJourney = journey;
          return { ...prev, [p.currentAge]: rec };
        });
        p.setActiveModal("national");
        triggerSeasonStats(p.standingResult, p.domesticCupResult, p.continentalCupResult, p.nationalCallupResult, tournamentVal);
      }).catch

getCareerPlayerAction({ playerId: savedPlayerId })
        .then((player) => {
          if (controller.signal.aborted || !player) return;
          const lastStats = (player.statsTimeline as any[]).at(-1);
          const lastStint = (player.clubStints as any[]).at(-1);
          if (!lastStats || !lastStint) { resetDraft(); setMode("setup"); setIsMounted(true); return; }

          statsProps.setPlayerId(savedPlayerId);
          statsProps.setPlayerName(player.name);
          statsProps.setPlayerNationality(player.nationality);
          statsProps.setPlayerDebutAge(player.debutAge);
          statsProps.setPlayerCareerLength(player.careerLengthYears);
          statsProps.setStatsTimeline(player.statsTimeline as any[]);
          statsProps.setClubStints(player.clubStints as any[]);
          statsProps.setAchievements((player.achievements as any) ?? { ballonDor: 0, trophies: [], seasonAwards: [] });

          if (player.seasonHistory && typeof player.seasonHistory === "object") {
            const restored: Record<number, SeasonRecord> = {};
            for (const [k, v] of Object.entries(player.seasonHistory as Record<string, any>)) {
              restored[parseInt(k)] = v as SeasonRecord;
            }
            statsProps.setSeasonRecords(restored);
          }

          statsProps.setCurrentAge(lastStats.age);
          statsProps.setCurrentOvr(lastStats.ovr);
          const statKeys = position === "GK"
            ? ["div", "han", "kic", "ref", "spd", "pos"]
            : ["pac", "sho", "pas", "dri", "def", "phy"];
          statsProps.setCurrentStats(Object.fromEntries(statKeys.map((k) => [k, lastStats[k] ?? 60])));

          const fullClub = clubs.find((c: any) => c.id === lastStint.clubId);
          statsProps.setCurrentClub({
            id: lastStint.clubId, name: lastStint.clubName,
            leagueId: lastStint.leagueId, leagueName: lastStint.leagueName,
            prestige: fullClub?.prestige ?? 3, continentalType: fullClub?.continentalType ?? "none",
          });
          if (savedContinentalCup) statsProps.setCurrentContinentalCup(savedContinentalCup);

          prevAgeRef.current = lastStats.age;
          setCareerSubStep("idle");
          setMode("career");
          setIsMounted(true);
        })
        .catch
